 public function testResearchRetainsAllOriginalOpportunityEvidenceDimensions():void {
  $r=new DigiForge\Research\Repository();$source=$r->createSource(['shop_key'=>'digital','name'=>'Offline source']);self::assertNotWPError($source);$observation=$r->ingest(['source_id'=>$source['id'],'title'=>'Offline dimensions']);self::assertNotWPError($observation);
  $dimensions=['demand','competition_saturation','seasonality','recipient_occasion','trend_overlay','provider_feasibility','expected_margin','policy_ip_risk','differentiation','confidence_uncertainty'];$candidate=$r->createCandidate(['shop_key'=>'digital','title'=>'Dimensions '.wp_generate_uuid4()]);self::assertNotWPError($candidate);
  foreach($dimensions as $name){$value='Unverified offline '.$name.' observation; no external commercial assertion.';$e=$r->addEvidence((int)$observation['id'],['evidence_type'=>$name,'value'=>$value,'provenance'=>['fixture_only'=>true]]);self::assertNotWPError($e);self::assertSame($name,$e['evidence_type']);self::assertSame($value,$e['value']);self::assertSame('1',$e['provenance']['fixture_only']);self::assertTrue($r->linkEvidence((int)$candidate['id'],(int)$e['id']));}
  global $wpdb;self::assertSame(10,(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.DigiForge\Database\Tables::research_candidate_evidence().' WHERE candidate_id=%d',$candidate['id'])));
 }
 public function testSignedWebhookPersistsReviewRequiredWithoutTrustingInternalIds():void {
  global $wpdb;$t=DigiForge\Database\Tables::class;$event='offline-'.wp_generate_uuid4();$body=(string)wp_json_encode(['event_type'=>'order.paid','order_id'=>'99001','shop_id'=>'99002','line_items'=>[['listing_id'=>'99003','product_version_id'=>999,'provider_mapping_id'=>999]],'currency'=>'USD']);$key='offline-fixture-key';$now=time();$headers=['webhook-id'=>$event,'webhook-timestamp'=>(string)$now,'webhook-signature'=>'v1,'.base64_encode(hash_hmac('sha256',$event.'.'.$now.'.'.$body,$key,true))];$secret='whsec_'.base64_encode($key);$intake=new DigiForge\Listings\EtsyWebhookIntake(new DigiForge\Listings\EtsyWebhookDeduplicator());
  $bad=$headers;$bad['webhook-signature']='v1,invalid';self::assertWPError($intake->accept($body,$bad,$secret,$now));self::assertNull((new DigiForge\Orders\Repository())->findByExternalReference('99001','99002'));
  $result=$intake->accept($body,$headers,$secret,$now);self::assertNotWPError($result);self::assertSame('REVIEW_REQUIRED',$result['persisted_order_state']);self::assertSame(0,$result['line_item_count']);self::assertFalse($result['fulfillment_authorized']);self::assertSame('REVIEW_REQUIRED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.$t::orders().' WHERE id=%d',$result['order_id'])));
  $again=$intake->accept($body,$headers,$secret,$now);self::assertNotWPError($again);self::assertFalse($again['process_permitted']);self::assertSame(0,(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.$t::order_line_items().' WHERE order_id=%d',$result['order_id'])));self::assertWPError($intake->accept($body,$headers,$secret,$now+301));
 }
 private function listing():array {
