  $dp=(new DigiForge\DigitalFactory\Repository())->create('digital_product',['product_id'=>$product['id'],'product_version_id'=>$v['id'],'name'=>'Fixture','category'=>'fixture']);self::assertNotWPError($dp);$l=(new DigiForge\Listings\Repository())->createListing(['product_version_id'=>$v['id'],'channel'=>'etsy','environment'=>'production','shop_reference'=>'digital','title'=>'Offline fixture','description'=>'No marketplace claim','price_amount'=>1,'currency'=>'USD']);self::assertNotWPError($l);return $l;
 }
