  self::assertSame(0,DigiForge\Orders\ApprovedPodMappingResolver::resolve((int)$l['id']+10000,(int)$l['product_version_id'],'production'));self::assertSame(0,DigiForge\Orders\ApprovedPodMappingResolver::resolve((int)$l['id'],(int)$l['product_version_id'],'sandbox'));
 }
