 public function testScopedEncryptedCredentialsAreOpaqueSingleUseAndNamespaceBound():void {
  global $wpdb;$t=DigiForge\Database\Tables::class;$now=current_time('mysql',true);self::assertSame(1,$wpdb->insert($t::integrations(),['provider'=>'etsy','connection_key'=>'offline-credential','display_name'=>'Offline credential fixture','config'=>'{}','environment'=>'sandbox','created_at'=>$now,'updated_at'=>$now]));$id=(int)$wpdb->insert_id;
  $scope=['state'=>'ETSY_SCOPED_CREDENTIAL_ACCESS_AUTHORIZED','single_use'=>true,'credential_name'=>'access_token','general_credential_access'=>false,'refresh_token_access'=>false,'credential_persistence_permitted'=>false,'credential_logging_permitted'=>false,'credential_retrieval_performed'=>false,'network_request_permitted'=>false,'external_execution_performed'=>false,'integration_id'=>$id,'operation_id'=>1];
  $retrieve=new DigiForge\Listings\EtsyScopedCredentialRetriever();self::assertWPError($retrieve->retrieve($scope));foreach(['access_token','keystring','shared_secret'] as $name){$plaintext='offline-fixture-'.$name;$cipher=DigiForge\Integrations\CredentialVault::encrypt($plaintext,DigiForge\Integrations\Repository::secretContext($id,$name));self::assertNotSame($plaintext,$cipher);self::assertSame(1,$wpdb->insert($t::integration_secrets(),['integration_id'=>$id,'secret_name'=>$name,'ciphertext'=>$cipher,'fingerprint'=>substr(hash('sha256',$plaintext),0,16),'created_at'=>$now,'updated_at'=>$now]));}
  $envelope=$retrieve->retrieve($scope);self::assertNotWPError($envelope);self::assertSame('[REDACTED]',(string)$envelope);self::assertStringNotContainsString('offline-fixture',(string)json_encode($envelope));self::assertStringNotContainsString('offline-fixture',print_r($envelope,true));$serialized=false;try{serialize($envelope);}catch(LogicException){$serialized=true;}self::assertTrue($serialized,'Scoped credential serialization must be denied.');$cloned=false;try{clone $envelope;}catch(Error){$cloned=true;}self::assertTrue($cloned,'Single-use scope cannot be duplicated by cloning.');self::assertWPError($envelope->consume($id+1,1,static fn()=>true));self::assertTrue($envelope->consume($id,1,static fn($token,$key):bool=>$token==='offline-fixture-access_token'&&$key==='offline-fixture-keystring:offline-fixture-shared_secret'));self::assertWPError($envelope->consume($id,1,static fn()=>true));$wrong=$scope;$wrong['integration_id']=$id+1;self::assertWPError($retrieve->retrieve($wrong));$wrong=$scope;$wrong['network_request_permitted']=true;self::assertWPError($retrieve->retrieve($wrong));
 }
